let P : @Measure (J → Ω) mJ :=
  @Measure.pi J (fun _ : J => Ω) instJ
    (fun _ : J => mΩ) (fun _ : J => μ)

let P₀ : @Measure (J → Ω) mJ₀ :=
  @Measure.pi J (fun _ : J => Ω) instJ
    (fun _ : J => m₀) (fun _ : J => μ₀)

let sourceCost : ℝ :=
  ((∫ ζ, fullTest ζ * Real.exp (S ζ) ∂P) +
    ∑ i : Fin n, ∫ ζ, deletedTest ζ i * Real.exp (Sdelete ζ i) ∂P) / I
